1	\chapter{Curves over a field}
2	\label{chap:Curves}
3	
4	Throughout this chapter \(k\) is a field. As in Chapter~\ref{chap:Challenge}, a \emph{smooth
5	curve} over \(k\) is a \(k\)-scheme which is smooth of relative dimension one, proper, and
6	geometrically irreducible over \(k\). This chapter provides the geometric substrate for the
7	genus: smooth schemes over a field are reduced, so a smooth curve is geometrically integral;
8	a proper geometrically integral scheme over a field has no global functions besides the
9	constants; the projective line carries two affine charts with polynomial section rings and
10	Laurent-polynomial overlap; the section rings of the standard smooth charts of a curve are
11	Dedekind domains, so the local rings of the curve are valuation rings and its
12	specialization order has height one; a rational function transcendental over \(k\) therefore
13	spreads out to a locally quasi-finite morphism \(C \to \PP^1\); and Zariski's main theorem
14	upgrades it to a finite one.
15	
16	\section{Smooth algebras over a domain are reduced}
17	
18	\begin{lemma}[Unramified flat algebras over a domain are reduced]
19	  \label{lem:unramified_flat_reduced}
20	  \lean{Algebra.FormallyUnramified.isReduced_of_isDomain}
21	  \leanok
22	  Let \(B\) be an integral domain and let \(S\) be a commutative \(B\)-algebra which is
23	  formally unramified, essentially of finite type, and flat over \(B\). Then \(S\) is reduced.
24	\end{lemma}
25	\begin{proof}
26	  \leanok
27	  Let \(K = \Frac B\) be the fraction field. The \(K\)-algebra \(K \otimes_B S\) is again
28	  formally unramified and essentially of finite type, both properties being stable under base
29	  change, and a formally unramified, essentially of finite type algebra over a field is
30	  reduced. It therefore suffices to embed \(S\) into \(K \otimes_B S\). The canonical map
31	  \(s \mapsto 1 \otimes s\) is, up to the isomorphism \(S \cong B \otimes_B S\), obtained from
32	  the injection \(B \hookrightarrow K\) by tensoring with \(S\); since \(S\) is flat over
33	  \(B\), it is injective. A subring of a reduced ring is reduced.
34	\end{proof}
35	
36	\begin{lemma}[\'Etale algebras over a domain are reduced]
37	  \label{lem:etale_reduced_domain}
38	  \lean{Algebra.Etale.isReduced_of_isDomain}
39	  \leanok
40	  An \'etale algebra over an integral domain is reduced.
41	\end{lemma}
42	\begin{proof}
43	  \leanok
44	  \uses{lem:unramified_flat_reduced}
45	  An \'etale algebra is formally unramified and of finite presentation, in particular
46	  essentially of finite type, and it is flat. Apply \ref{lem:unramified_flat_reduced}.
47	\end{proof}
48	
49	\begin{lemma}[Standard smooth homomorphisms out of a domain]
50	  \label{lem:standard_smooth_reduced_ringhom}
51	  \lean{RingHom.IsStandardSmooth.isReduced_of_isDomain}
52	  \leanok
53	  Let \(B\) be an integral domain and let \(B \to S\) be a standard smooth ring homomorphism,
54	  that is, one admitting a presentation \(S = B[x_1,\dots,x_n]/(f_1,\dots,f_c)\) in which the
55	  Jacobian matrix \((\partial f_u/\partial x_v)_{u,v \le c}\) has invertible determinant in
56	  \(S\). Then \(S\) is reduced.
57	\end{lemma}
58	\begin{proof}
59	  \leanok
60	  \uses{lem:etale_reduced_domain}
61	  By the structure theorem for standard smooth algebras, \(S\) is \'etale over a polynomial
62	  ring over the base: there are \(m\) and a factorization
63	  \(B \to B[x_1,\dots,x_m] \to S\) with the second map \'etale. A polynomial ring over an
64	  integral domain is an integral domain, so \ref{lem:etale_reduced_domain} applies.
65	\end{proof}
66	
67	\begin{lemma}[Standard smooth algebras over a domain]
68	  \label{lem:standard_smooth_reduced}
69	  \lean{Algebra.IsStandardSmooth.isReduced_of_isDomain}
70	  \leanok
71	  A standard smooth algebra over an integral domain is reduced.
72	\end{lemma}
73	\begin{proof}
74	  \leanok
75	  \uses{lem:standard_smooth_reduced_ringhom}
76	  The structure homomorphism is a standard smooth ring homomorphism out of a domain; apply
77	  \ref{lem:standard_smooth_reduced_ringhom}.
78	\end{proof}
79	
80	\begin{theorem}[Smooth schemes over a field are reduced]
81	  \label{thm:smooth_reduced_field}
82	  \lean{AlgebraicGeometry.Smooth.isReduced_of_field}
83	  \leanok
84	  Let \(K\) be a field and let \(X\) be a scheme which is smooth over \(\Spec K\). Then \(X\)
85	  is reduced.
86	\end{theorem}
87	\begin{proof}
88	  \leanok
89	  \uses{lem:standard_smooth_reduced_ringhom}
90	  A smooth morphism is, locally on the source and the target, standard smooth: every point
91	  \(x \in X\) has an affine open neighbourhood \(V\), mapping into an affine open \(U\) of the
92	  base, such that the induced ring homomorphism \(\Gamma(U) \to \Gamma(V)\) is standard
93	  smooth. Since \(\Spec K\) has a single point and \(U\) is a nonempty open subset containing
94	  the image of \(x\), we have \(U = \Spec K\), and \(\Gamma(U) \cong K\) is a field, in
95	  particular a domain. By \ref{lem:standard_smooth_reduced_ringhom} the ring \(\Gamma(V)\) is
96	  reduced, hence the affine scheme \(V\) is reduced. The opens \(V\) cover \(X\), and a scheme
97	  covered by reduced open subschemes is reduced.
98	\end{proof}
99	
100	\begin{theorem}[Smooth morphisms are geometrically reduced]
101	  \label{thm:smooth_geometrically_reduced}
102	  \lean{AlgebraicGeometry.Smooth.geometricallyReduced}
103	  \leanok
104	  A smooth morphism of schemes \(f : X \to Y\) is geometrically reduced: for every field \(K\)
105	  and every morphism \(\Spec K \to Y\), the base change \(X \times_Y \Spec K\) is a reduced
106	  scheme.
107	\end{theorem}
108	\begin{proof}
109	  \leanok
110	  \uses{thm:smooth_reduced_field}
111	  Smoothness is stable under base change, so the projection
112	  \(X \times_Y \Spec K \to \Spec K\) is smooth; apply \ref{thm:smooth_reduced_field}.
113	\end{proof}
114	
115	\begin{lemma}[Smooth of relative dimension one implies smooth]
116	  \label{lem:smooth_of_relDim_one}
117	  \lean{AlgebraicGeometry.Smooth.of_smoothOfRelativeDimension_one}
118	  \leanok
119	  A morphism of schemes which is smooth of relative dimension one is smooth.
120	\end{lemma}
121	\begin{proof}
122	  \leanok
123	  A morphism smooth of some relative dimension is smooth.
124	\end{proof}
125	
126	\begin{lemma}[Smooth of a relative dimension implies geometrically reduced]
127	  \label{lem:relDim_geometrically_reduced}
128	  \lean{AlgebraicGeometry.SmoothOfRelativeDimension.geometricallyReduced}
129	  \leanok
130	  For every \(n\), a morphism of schemes which is smooth of relative dimension \(n\) is
131	  geometrically reduced.
132	\end{lemma}
133	\begin{proof}
134	  \leanok
135	  \uses{thm:smooth_geometrically_reduced}
136	  Such a morphism is smooth; apply \ref{thm:smooth_geometrically_reduced}.
137	\end{proof}
138	
139	\begin{theorem}[Smooth and geometrically irreducible implies geometrically integral]
140	  \label{thm:smooth_geometrically_integral}
141	  \lean{AlgebraicGeometry.Smooth.geometricallyIntegral}
142	  \leanok
143	  A smooth, geometrically irreducible morphism of schemes is geometrically integral: every
144	  base change to the spectrum of a field is an integral scheme.
145	\end{theorem}
146	\begin{proof}
147	  \leanok
148	  \uses{thm:smooth_geometrically_reduced}
149	  Every base change to the spectrum of a field is reduced
150	  (\ref{thm:smooth_geometrically_reduced}) and irreducible (geometric irreducibility), and a
151	  reduced scheme with irreducible --- in particular nonempty --- underlying space is integral.
152	\end{proof}
153	
154	\begin{theorem}[Relative-dimension form]
155	  \label{thm:relDim_geometrically_integral}
156	  \lean{AlgebraicGeometry.SmoothOfRelativeDimension.geometricallyIntegral}
157	  \leanok
158	  For every \(n\), a geometrically irreducible morphism of schemes which is smooth of relative
159	  dimension \(n\) is geometrically integral.
160	\end{theorem}
161	\begin{proof}
162	  \leanok
163	  \uses{thm:smooth_geometrically_integral}
164	  Such a morphism is smooth; apply \ref{thm:smooth_geometrically_integral}.
165	\end{proof}
