167	\section{Schemes over a field: the topological substrate}
168	
169	In this section \(X\) is a scheme over \(k\), that is, a scheme equipped with a structure
170	morphism \(X \to \Spec k\).
171	
172	\begin{lemma}[Irreducibility]
173	  \label{lem:irreducible_of_geomirred}
174	  \lean{AlgebraicGeometry.irreducibleSpace_left_of_geometricallyIrreducible}
175	  \leanok
176	  If \(X\) is geometrically irreducible over \(k\), then the underlying topological space of
177	  \(X\) is irreducible; in particular \(X\) is nonempty.
178	\end{lemma}
179	\begin{proof}
180	  \leanok
181	  Geometric irreducibility applied to the trivial extension \(k \to k\) says that
182	  \(X \times_{\Spec k} \Spec k \cong X\) is irreducible.
183	\end{proof}
184	
185	\begin{lemma}[Quasi-compactness]
186	  \label{lem:curve_compact}
187	  \lean{AlgebraicGeometry.compactSpace_left_of_quasiCompact}
188	  \leanok
189	  If \(X\) is quasi-compact over \(\Spec k\) (for instance proper), then the underlying
190	  topological space of \(X\) is quasi-compact.
191	\end{lemma}
192	\begin{proof}
193	  \leanok
194	  \(\Spec k\) is a one-point space, hence quasi-compact, and \(X\) is the preimage of it
195	  under a quasi-compact morphism.
196	\end{proof}
197	
198	\begin{lemma}[Quasi-separatedness]
199	  \label{lem:curve_quasiseparated}
200	  \lean{AlgebraicGeometry.quasiSeparatedSpace_left_of_quasiSeparated}
201	  \leanok
202	  If \(X\) is quasi-separated over \(\Spec k\) (for instance proper), then the underlying
203	  topological space of \(X\) is quasi-separated: the intersection of any two quasi-compact
204	  opens is quasi-compact.
205	\end{lemma}
206	\begin{proof}
207	  \leanok
208	  \(\Spec k\) is affine, hence a quasi-separated scheme, and a scheme quasi-separated over a
209	  quasi-separated scheme is quasi-separated.
210	\end{proof}
211	
212	\begin{proposition}[Integrality]
213	  \label{prop:curve_integral}
214	  \lean{AlgebraicGeometry.isIntegral_left_of_geometricallyReduced}
215	  \leanok
216	  If \(X\) is geometrically reduced and geometrically irreducible over \(k\), then \(X\) is an
217	  integral scheme.
218	\end{proposition}
219	\begin{proof}
220	  \leanok
221	  \uses{lem:irreducible_of_geomirred}
222	  Applying geometric reducedness to the trivial extension \(k \to k\) shows that \(X\) is
223	  reduced, and \(X\) is irreducible by \ref{lem:irreducible_of_geomirred}. A reduced scheme
224	  with irreducible underlying space is integral.
225	\end{proof}
226	
227	\section{Global sections of a proper geometrically integral scheme}
228	
229	\begin{lemma}[Pushout of a field extension along itself]
230	  \label{lem:pushout_field_epi}
231	  \lean{CommRingCat.epi_of_isPushout_of_isField}
232	  \leanok
233	  Let \(\varphi : A \to B\) and \(\psi : A \to C\) be homomorphisms of commutative rings with
234	  \(B\) nontrivial, and let \(D\), with coprojections \(\iota_B : B \to D\) and
235	  \(\iota_C : C \to D\), be a pushout of \((\varphi, \psi)\) (for instance
236	  \(D = B \otimes_A C\)). Assume that \(D\) is a field and that there is a ring isomorphism
237	  \(e : C \cong B\) with \(e \circ \psi = \varphi\). Then \(\varphi\) is an epimorphism in the
238	  category of commutative rings.
239	\end{lemma}
240	\begin{proof}
241	  \leanok
242	  Let \(\mu : D \to B\) be the homomorphism with \(\mu \circ \iota_B = \id_B\) and
243	  \(\mu \circ \iota_C = e\), given by the universal property of the pushout (the two maps
244	  agree on \(A\) because \(e \circ \psi = \varphi\)). Since \(D\) is a field and \(B\) is
245	  nontrivial, \(\mu\) is injective; it is surjective because \(\mu \circ \iota_B = \id_B\).
246	  Hence \(\mu\) is an isomorphism, and from
247	  \(\mu \circ \iota_B = \id_B = \mu \circ (\iota_C \circ e^{-1})\) we conclude
248	  \(\iota_B = \iota_C \circ e^{-1}\).
249	
250	  Now let \(u, v : B \to W\) satisfy \(u \circ \varphi = v \circ \varphi\). Then
251	  \(u \circ \varphi = (v \circ e) \circ \psi\), so there is
252	  \(w : D \to W\) with \(w \circ \iota_B = u\) and \(w \circ \iota_C = v \circ e\). Therefore
253	  \[
254	    u = w \circ \iota_B = w \circ \iota_C \circ e^{-1} = v \circ e \circ e^{-1} = v,
255	  \]
256	  which proves that \(\varphi\) is an epimorphism.
257	\end{proof}
258	
259	\begin{lemma}[Global sections form a field]
260	  \label{lem:sections_field}
261	  \lean{AlgebraicGeometry.isField_of_universallyClosed_of_isField}
262	  \leanok
263	  Let \(R\) be a commutative ring which is a field, let \(X\) be an integral scheme, and let
264	  \(f : X \to \Spec R\) be universally closed. Then \(\Gamma(X, \struct X)\) is a field.
265	\end{lemma}
266	\begin{proof}
267	  \leanok
268	  \(\Gamma(X, \struct X)\) is an integral domain because \(X\) is integral. Since \(f\) is
269	  universally closed, the induced ring homomorphism
270	  \(R \cong \Gamma(\Spec R, \struct{\Spec R}) \to \Gamma(X, \struct X)\) is an integral
271	  extension. A domain which is integral over a field is a field.
272	\end{proof}
273	
274	\begin{theorem}[Constant functions on a proper geometrically integral scheme]
275	  \label{thm:sections_k}
276	  \lean{AlgebraicGeometry.bijective_appTop_of_isProper_of_geometricallyIntegral}
277	  \leanok
278	  Let \(K\) be a field and let \(X\) be a scheme, proper and geometrically integral over
279	  \(K\). Then the ring homomorphism
280	  \(\Gamma(\Spec K, \struct{\Spec K}) \to \Gamma(X, \struct X)\) induced by the structure
281	  morphism is bijective; identifying \(\Gamma(\Spec K, \struct{\Spec K}) = K\), this says
282	  \(\Gamma(X, \struct X) = K\).
283	\end{theorem}
284	\begin{proof}
285	  \leanok
286	  \uses{lem:pushout_field_epi, lem:sections_field, lem:curve_compact, lem:curve_quasiseparated}
287	  Write \(A = \Gamma(X, \struct X)\) and let \(\varphi : K \to A\) be the map in question.
288	  Applying geometric integrality to the trivial extension \(K \to K\) shows that \(X\) is
289	  integral; in particular \(X\) is nonempty and \(A\) is a nontrivial domain, so \(\varphi\),
290	  a ring homomorphism out of a field into a nontrivial ring, is injective. By
291	  \ref{lem:sections_field} (properness includes universal closedness), \(A\) is a field, and
292	  since \(f\) is proper, \(A\) is moreover a finite \(K\)-module. As a finite ring
293	  homomorphism is surjective as soon as it is an epimorphism of commutative rings, it remains
294	  to prove that \(\varphi\) is an epimorphism.
295	
296	  Let \(q : \Spec A \to \Spec K\) be the morphism induced by \(\varphi\) and form the base
297	  change \(Y = X \times_{\Spec K} \Spec A\). Since \(A\) is a field, geometric integrality of
298	  \(f\) makes \(Y\) integral, and the projection \(Y \to \Spec A\) is universally closed as a
299	  base change of \(f\); hence \(D := \Gamma(Y, \struct Y)\) is a field by
300	  \ref{lem:sections_field}. On the other hand, \(X\) is quasi-compact and quasi-separated as
301	  a topological space (\ref{lem:curve_compact}, \ref{lem:curve_quasiseparated}), and \(q\) is
302	  flat because every vector space over \(K\) is flat; flat base change for global sections
303	  therefore exhibits the square of section rings
304	  \[
305	    \begin{array}{ccc}
306	      K & \longrightarrow & A \\
307	      \downarrow & & \downarrow \\
308	      A & \longrightarrow & D
309	    \end{array}
310	  \]
311	  (left column \(\varphi\), top row \(\varphi\) transported through the canonical isomorphism
312	  \(\Gamma(\Spec A, \struct{\Spec A}) \cong A\)) as a pushout square of commutative rings,
313	  \(D \cong A \otimes_K A\). Its pushout \(D\) is a field and its two legs are isomorphic
314	  copies of \(\varphi\), so \(\varphi\) is an epimorphism by \ref{lem:pushout_field_epi}.
315	\end{proof}
316	
317	\begin{corollary}[Isomorphism form]
318	  \label{cor:sections_iso}
319	  \lean{AlgebraicGeometry.isIso_appTop_of_isProper_of_geometricallyIntegral}
320	  \leanok
321	  In the situation of \ref{thm:sections_k}, the induced map
322	  \(\Gamma(\Spec K, \struct{\Spec K}) \to \Gamma(X, \struct X)\) is an isomorphism of rings.
323	\end{corollary}
324	\begin{proof}
325	  \leanok
326	  \uses{thm:sections_k}
327	  A bijective ring homomorphism is an isomorphism.
328	\end{proof}
329	
330	\begin{corollary}[Global sections of the curve]
331	  \label{cor:curve_sections}
332	  \lean{AlgebraicGeometry.isIso_hom_appTop_of_geometricallyReduced}
333	  \leanok
334	  Let \(C\) be a scheme over \(k\) which is proper, geometrically irreducible and
335	  geometrically reduced over \(k\). Then the structure morphism induces an isomorphism
336	  \(\Gamma(\Spec k, \struct{\Spec k}) \cong \Gamma(C, \struct C)\); that is,
337	  \(\Gamma(C, \struct C) = k\).
338	\end{corollary}
339	\begin{proof}
340	  \leanok
341	  \uses{cor:sections_iso}
342	  Every base change of \(C\) to the spectrum of a field is reduced and irreducible, hence
343	  integral; so \(C\) is geometrically integral over \(k\) and \ref{cor:sections_iso} applies.
344	\end{proof}
345	
346	\begin{remark}[The smooth curve]
347	  \label{rem:curve_bundle}
348	  \uses{lem:smooth_of_relDim_one, lem:relDim_geometrically_reduced,
349	    thm:relDim_geometrically_integral, lem:irreducible_of_geomirred, lem:curve_compact,
350	    lem:curve_quasiseparated, prop:curve_integral, cor:curve_sections}
351	  \leanok
352	  Let \(C\) be a smooth curve over \(k\), i.e.\ proper, smooth of relative dimension one and
353	  geometrically irreducible over \(k\), as in Chapter~\ref{chap:Challenge}. Combining the
354	  above: \(C\) is smooth over \(k\) (\ref{lem:smooth_of_relDim_one}), geometrically reduced
355	  (\ref{lem:relDim_geometrically_reduced}) and geometrically integral
356	  (\ref{thm:relDim_geometrically_integral}); its underlying space is irreducible
357	  (\ref{lem:irreducible_of_geomirred}), quasi-compact (\ref{lem:curve_compact}) and
358	  quasi-separated (\ref{lem:curve_quasiseparated}); \(C\) is an integral scheme
359	  (\ref{prop:curve_integral}); and \(\Gamma(C, \struct C) = k\) (\ref{cor:curve_sections}).
360	\end{remark}
361	
362	\section{The projective line and its charts}
363	
364	Let \(A = k[X_0, X_1]\) be the polynomial ring in two variables, graded by total degree. For a
365	homogeneous element \(f \in A\) we write \(A_{(f)}\) for the degree-zero part of the
366	localization \(A_f\); its elements are fractions \(a/f^n\) with \(a\) homogeneous of degree
367	\(n \deg f\).
368	
369	\begin{definition}[The projective line]
370	  \label{def:P1}
371	  \lean{AlgebraicGeometry.P1}
372	  \leanok
373	  The projective line over \(k\) is \(\PP^1 = \Proj A\), the Proj of the graded ring
374	  \(A = k[X_0, X_1]\).
375	\end{definition}
376	
377	\begin{definition}[Degree zero]
378	  \label{def:P1_gradeZero}
379	  \lean{AlgebraicGeometry.P1.gradeZeroAlgEquiv}
380	  \leanok
381	  The inclusion of constants \(k \to A_0\) into the degree-zero part of \(A\) is an
382	  isomorphism of \(k\)-algebras.
383	\end{definition}
384	\begin{proof}
385	  \leanok
386	  It is injective because a nonzero constant polynomial is nonzero, and surjective because a
387	  polynomial which is homogeneous of degree zero is constant.
388	\end{proof}
389	
390	\begin{definition}[Structure morphism]
391	  \label{def:P1_structureMap}
392	  \lean{AlgebraicGeometry.P1.structureMap}
393	  \uses{def:P1, def:P1_gradeZero}
394	  \leanok
395	  The structure morphism \(\PP^1 \to \Spec k\) is the canonical morphism
396	  \(\Proj A \to \Spec A_0\) followed by the isomorphism \(\Spec A_0 \cong \Spec k\) induced by
397	  \ref{def:P1_gradeZero}.
398	\end{definition}
399	
400	\begin{theorem}[Properness of the projective line]
401	  \label{thm:P1_proper}
402	  \lean{AlgebraicGeometry.P1.isProper_structureMap}
403	  \uses{def:P1_structureMap}
404	  \leanok
405	  \(\PP^1\) is proper over \(k\).
406	\end{theorem}
407	\begin{proof}
408	  \leanok
409	  \uses{def:P1_gradeZero}
410	  \(A\) is a finitely generated algebra over its degree-zero part \(A_0 = k\) (generated by
411	  \(X_0\) and \(X_1\)), and the Proj of a graded ring which is finitely generated over its
412	  degree-zero part is proper over the spectrum of the degree-zero part. Composing with the
413	  isomorphism \(\Spec A_0 \cong \Spec k\) preserves properness.
414	\end{proof}
415	
416	\begin{definition}[The projective line as a scheme over \(k\)]
417	  \label{def:P1_asOver}
418	  \lean{AlgebraicGeometry.P1.asOver}
419	  \uses{def:P1_structureMap}
420	  \leanok
421	  \(\PP^1\), regarded as a scheme over \(k\) via the structure morphism of
422	  \ref{def:P1_structureMap}.
423	\end{definition}
424	
425	\begin{definition}[The standard charts]
426	  \label{def:P1_chartOpen}
427	  \lean{AlgebraicGeometry.P1.chartOpen}
428	  \uses{def:P1}
429	  \leanok
430	  For \(i \in \{0,1\}\), the chart \(U_i = D_+(X_i) \subseteq \PP^1\) is the basic open locus
431	  where the homogeneous coordinate \(X_i\) does not vanish.
432	\end{definition}
433	
434	\begin{lemma}[The charts are affine]
435	  \label{lem:P1_chartOpen_affine}
436	  \lean{AlgebraicGeometry.P1.isAffineOpen_chartOpen}
437	  \uses{def:P1_chartOpen}
438	  \leanok
439	  Each chart \(U_i\) is an affine open of \(\PP^1\).
440	\end{lemma}
441	\begin{proof}
442	  \leanok
443	  \(X_i\) is homogeneous of degree \(1 > 0\), and the basic open of \(\Proj\) at a homogeneous
444	  element of positive degree is affine.
445	\end{proof}
446	
447	\begin{lemma}[The charts cover]
448	  \label{lem:P1_chartOpen_sup}
449	  \lean{AlgebraicGeometry.P1.chartOpen_sup}
450	  \uses{def:P1_chartOpen}
451	  \leanok
452	  \(U_0 \cup U_1 = \PP^1\).
453	\end{lemma}
454	\begin{proof}
455	  \leanok
456	  A point of \(\Proj A\) is a homogeneous prime ideal \(\mathfrak p\) of \(A\) not containing
457	  the irrelevant ideal \(A_+\). Every monomial of positive degree is divisible by \(X_0\) or
458	  by \(X_1\), so if both \(X_0 \in \mathfrak p\) and \(X_1 \in \mathfrak p\) then
459	  \(A_+ \subseteq \mathfrak p\), a contradiction. Hence every point avoids some \(X_i\), i.e.\
460	  lies in \(U_0 \cup U_1\).
461	\end{proof}
462	
463	\begin{lemma}[The chart overlap]
464	  \label{lem:P1_chartOpen_inf}
465	  \lean{AlgebraicGeometry.P1.chartOpen_inf}
466	  \uses{def:P1_chartOpen}
467	  \leanok
468	  \(U_0 \cap U_1 = D_+(X_0 X_1)\).
469	\end{lemma}
470	\begin{proof}
